return $input.all().map((item, index) => {
  const topicData = $('extrae contenido').all()[index]?.json || {};
  const searxResults = item.json?.results || [];

  const contexto = searxResults
    .slice(0, 3)
    .map(r => r.title + ': ' + r.content)
    .join(' | ')
    .slice(0, 500);

  return {
    json: {
      ...topicData,
      contexto_adicional: contexto || 'Sin contexto adicional'
    }
  };
});

const response = $input.first().json;
const topics = response.topic_list.topics;

return topics.map(topic => ({
  json: {
    id: topic.id,
    titulo: topic.title,
    url: `https://replit.discourse.group/t/${topic.slug}/${topic.id}`,
    fecha: topic.created_at,
    vistas: topic.views,
    respuestas: topic.reply_count
  }
}));

return $input.all().map(item => {
  const raw = item.json;
  const firstPost = raw?.post_stream?.posts?.[0];

  const content = firstPost?.cooked
    ? firstPost.cooked
        .replace(/<[^>]*>/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 2000)
    : 'Sin contenido';

  return {
    json: {
      id: raw.id,
      titulo: raw.title,
      url: `https://replit.discourse.group/t/${raw.slug}/${raw.id}`,
      contenido: content,
      autor: firstPost?.username || 'desconocido',
      fecha: raw.created_at,
      tags: raw.tags || []
    }
  };
});

return $input.all().map((item, index) => {
  const datosOriginales = $('extrae contenido').all()[index]?.json || {};

  let raw = item.json?.text || '{}';
  raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  let analisis = {};
  try {
    analisis = JSON.parse(raw);
  } catch(e) {
    analisis = {
      tiene_problematica: false,
      problematica: 'Error al parsear',
      area_social: 'N/A',
      area_tecnologica: 'N/A',
      solucion_sugerida: 'N/A',
      _error: e.message
    };
  }

  // --- Validación heurística de coherencia ---
  function extraerPalabras(texto) {
    if (!texto || typeof texto !== 'string') return new Set();
    return new Set(
      texto.toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // quita tildes
        .replace(/[^a-z0-9\s]/g, '')
        .split(/\s+/)
        .filter(w => w.length > 4) // ignora palabras cortas (de, la, en...)
    );
  }

  const palabrasProblematica = extraerPalabras(analisis.problematica);
  const palabrasSolucion     = extraerPalabras(analisis.solucion_sugerida);

  let palabrasComunes = 0;
  for (const palabra of palabrasSolucion) {
    if (palabrasProblematica.has(palabra)) palabrasComunes++;
  }

  const solucionValida = typeof analisis.solucion_sugerida === 'string' &&
                         analisis.solucion_sugerida.trim().length >= 20 &&
                         !['n/a', 'no aplica', 'ninguna', 'sin solucion'].includes(
                           analisis.solucion_sugerida.trim().toLowerCase()
                         );

  const coherente = solucionValida && (palabrasComunes >= 1 || palabrasSolucion.size === 0);

  return {
    json: {
      id: datosOriginales.id,
      titulo: datosOriginales.titulo,
      url: datosOriginales.url,
      fecha: datosOriginales.fecha,
      analisis: analisis,
      validacion: {
        ok: analisis.tiene_problematica !== undefined,
        tiene_problematica: analisis.tiene_problematica,
        solucion_coherente: coherente  // ← campo nuevo
      }
    }
  };
});
